<?= $this->section('content') ?>
<?php $statusLabels=['pending'=>'Menunggu','approved'=>'Terbit','rejected'=>'Ditolak','hidden'=>'Disembunyikan']; ?>
<header class="mb-8"><p class="section-kicker">Konten pelanggan</p><h1 class="mt-2 font-display text-3xl sm:text-4xl">Moderasi ulasan</h1><p class="mt-3 max-w-3xl text-ink-muted">Periksa relevansi komentar dan foto. Isi asli dan rating pelanggan tidak dapat diedit.</p></header>
<nav class="mb-6 flex gap-2 overflow-x-auto pb-1" aria-label="Filter ulasan"><a class="filter-chip <?= $activeStatus===''?'is-active':'' ?>" href="<?= site_url('panel/reviews') ?>">Semua</a><?php foreach($statusLabels as $value=>$label): ?><a class="filter-chip <?= $activeStatus===$value?'is-active':'' ?>" href="<?= site_url('panel/reviews?status='.$value) ?>"><?= esc($label) ?> · <?= (int)($counts[$value]??0) ?></a><?php endforeach ?></nav>
<?php if($reviews===[]): ?><div class="panel-card p-8"><p class="font-display text-2xl">Belum ada ulasan pada filter ini.</p></div><?php else: ?><div class="grid gap-5 lg:grid-cols-2"><?php foreach($reviews as $review): ?><article class="panel-card overflow-hidden"><header class="flex items-start justify-between gap-4 p-5"><div><p class="text-xs font-bold uppercase tracking-wider text-brand-chili"><?= esc($review['product_name'].' · '.$review['variant_name']) ?></p><h2 class="mt-2 font-display text-xl"><?= esc($review['display_name']?:'Anonim') ?></h2><p class="mt-1 text-sm text-ink-muted"><?= esc($review['sale_number']) ?> · <?= esc(date('d/m/Y H:i',strtotime($review['created_at']))) ?></p></div><span class="status-label bg-brand-sun"><?= esc($statusLabels[$review['status']]??$review['status']) ?></span></header><div class="border-y border-border-warm bg-[#FFFCF4] p-5"><p class="text-xl text-brand-chili" aria-label="Rating <?= (int)$review['rating'] ?> dari 5"><?= str_repeat('★',(int)$review['rating']).str_repeat('☆',5-(int)$review['rating']) ?></p><p class="mt-3 leading-7"><?= nl2br(esc($review['comment'])) ?></p><?php if($review['sale_fully_refunded']): ?><p class="mt-3 text-xs font-bold text-status-warning">Penanda internal: transaksi direfund penuh setelah ulasan masuk.</p><?php endif ?></div><?php if(!empty($imagesByReview[$review['id']])): ?><div class="grid grid-cols-3 gap-2 p-5"><?php foreach($imagesByReview[$review['id']] as $image): ?><a href="<?= site_url('ulasan/foto/'.$image['id']) ?>" target="_blank" rel="noopener"><img class="aspect-square w-full border border-border-warm object-cover" src="<?= site_url('ulasan/foto/'.$image['id']) ?>" alt="Foto ulasan pelanggan"></a><?php endforeach ?></div><?php endif ?><?php if($review['status']==='pending'): ?><div class="grid gap-4 border-t border-border-warm p-5 sm:grid-cols-2"><form action="<?= site_url('panel/reviews/'.$review['id'].'/moderate') ?>" method="post" data-confirm-form="Terbitkan ulasan ini di halaman produk?"><?= csrf_field() ?><input type="hidden" name="action" value="approve"><button class="button-primary w-full" type="submit">Setujui dan terbitkan</button></form><form action="<?= site_url('panel/reviews/'.$review['id'].'/moderate') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="reject"><label class="form-label" for="reject-review-<?= (int)$review['id'] ?>">Alasan penolakan</label><textarea class="form-input min-h-20" id="reject-review-<?= (int)$review['id'] ?>" name="reason" minlength="5" maxlength="500" required></textarea><button class="button-secondary mt-2 w-full" type="submit">Tolak ulasan</button></form></div><?php elseif($review['status']==='approved'): ?><form action="<?= site_url('panel/reviews/'.$review['id'].'/moderate') ?>" method="post" class="border-t border-border-warm p-5"><?= csrf_field() ?><input type="hidden" name="action" value="hide"><label class="form-label" for="hide-review-<?= (int)$review['id'] ?>">Alasan menyembunyikan</label><div class="grid gap-2 sm:grid-cols-[1fr_auto]"><input class="form-input" id="hide-review-<?= (int)$review['id'] ?>" name="reason" minlength="5" maxlength="500" required><button class="button-secondary" type="submit">Sembunyikan</button></div></form><?php elseif($review['moderation_reason']): ?><p class="border-t border-border-warm p-5 text-sm"><strong>Alasan moderasi:</strong> <?= esc($review['moderation_reason']) ?></p><?php endif ?></article><?php endforeach ?></div><?php endif ?>
